var list_ships_default = defineTool({
  name: "list_ships",
  title: "Daftar kapal",
  description: "List ship unloading records (kapal) for the signed-in user, newest first. Optionally filter by month, year, or PIPP status.",
  inputSchema: {
    year: z.number().int().min(2e3).max(2100).optional().describe("Filter by year of tanggal."),
    month: z.number().int().min(1).max(12).optional().describe("Filter by month (1-12) of tanggal."),
    done_pipp: z.boolean().optional().describe("Filter by PIPP completion status."),
    limit: z.number().int().min(1).max(200).default(50).describe("Max rows to return.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ year, month, done_pipp, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    let query = supabase.from("kapal_data").select(
      "id, nama_kapal, tanggal, jenis_pendataan, alat_tangkap, posisi_dermaga, tanda_selar_gt, tanda_selar_no, tanda_selar_huruf, done_pipp, notes"
    ).order("tanggal", { ascending: false }).limit(limit ?? 50);
    if (typeof done_pipp === "boolean") query = query.eq("done_pipp", done_pipp);
    if (year) {
      const m = month ?? 1;
      const start = month ? `${year}-${String(m).padStart(2, "0")}-01` : `${year}-01-01`;
      const endDate = month ? new Date(Date.UTC(year, m, 1)) : new Date(Date.UTC(year + 1, 0, 1));
      query = query.gte("tanggal", start).lt("tanggal", endDate.toISOString().slice(0, 10));
    }
    const { data, error } = await query;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? [], null, 2) }],
      structuredContent: { ships: data ?? [] }
    };
  }
});

// src/lib/mcp/tools/get-ship-detail.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var get_ship_detail_default = defineTool2({
  name: "get_ship_detail",
  title: "Detail kapal & hasil bongkar",
  description: "Get one ship record with all of its catch entries (jenis, berat) plus totals per species.",
  inputSchema: {
    kapal_id: z2.string().uuid().describe("The ship record id returned by list_ships.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ kapal_id }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const { data: ship, error: shipError } = await supabase.from("kapal_data").select("*").eq("id", kapal_id).maybeSingle();
    if (shipError) return { content: [{ type: "text", text: shipError.message }], isError: true };
    if (!ship) return { content: [{ type: "text", text: "Kapal tidak ditemukan." }], isError: true };
    const { data: entries, error: entriesError } = await supabase.from("entries").select("id, jenis, berat, waktu_input").eq("kapal_id", kapal_id).order("waktu_input", { ascending: true });
    if (entriesError) {
      return { content: [{ type: "text", text: entriesError.message }], isError: true };
    }
    const perSpecies = {};
    let total = 0;
    for (const e of entries ?? []) {
      perSpecies[e.jenis] = (perSpecies[e.jenis] ?? 0) + Number(e.berat);
      total += Number(e.berat);
    }
    const payload = {
      ship,
      entries: entries ?? [],
      totals: { per_species: perSpecies, total_kg: total }
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

